'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function stream(chunks, options) {
  const parser = createParser(options);
  const result = [];
  for (const chunk of chunks) result.push(...parser.push(chunk));
  result.push(...parser.end());
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push(''), Error);
  return result;
}

test('grammar is invariant across every pair of chunk boundaries', () => {
  const cases = [
    ['', []], ['\uFEFF', []], ['\n', [['']]], ['\n\n', [[''], ['']]],
    ['\r\n', [['']]], ['\r\r\n\n', [[''], [''], ['']]],
    ['a\n', [['a']]], ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
    [',', [['', '']]], ['left,,right,', [['left', '', 'right', '']]],
    ['""', [['']]], ['""""', [['"']]], ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
    ['"a\r\nb\rc\nd",tail\r\n', [['a\r\nb\rc\nd', 'tail']]],
    ['a"b,"c", "d"', [['a"b', 'c', ' "d"']]],
    ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
    ['\uFEFF\uFEFF', [['\uFEFF']]], ['"a",\n', [['a', '']]],
    ['😀,"😃"', [['😀', '😃']]],
  ];
  for (const [text, expected] of cases) {
    assert.deepEqual(parse(text), expected);
    for (let first = 0; first <= text.length; first++) {
      for (let second = first; second <= text.length; second++) {
        assert.deepEqual(stream(['', text.slice(0, first), '', text.slice(first, second), '', text.slice(second), '']), expected);
      }
    }
    assert.deepEqual(stream(text.split('')), expected);
  }
});

test('push emits at CR immediately, never replays records, and buffers partial rows', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('a\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\nb,'), []);
  assert.deepEqual(parser.push('c\n\n"d\r'), [['b', 'c'], ['']]);
  assert.deepEqual(parser.push('\ne"'), []);
  assert.deepEqual(parser.push(',f\r'), [['d\r\ne', 'f']]);
  assert.deepEqual(parser.push('\nlast,'), []);
